        fflush(::core::ptr::null_mut::<FILE>());
        fprintf(
            sp0,
            b"nconnnodemin must be nonnegative\n\0" as *const u8 as *const ::core::ffi::c_char,
        );
        exit(ABNORMAL_EXIT);
